use crate::aap::caps::state_rw;
use std::collections::BTreeSet;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let date = published.date;

        // Mark items seen only once the digest has actually gone out, so an
        // unpublished run leaves them eligible for the next one.
        if !published.published {
            return RunReport { date, recorded: 0 };
        }

        let mut written: BTreeSet<&str> = BTreeSet::new();
        for id in published.considered.iter() {
            let key = id.as_str();
            if key.is_empty() || written.contains(key) {
                continue;
            }
            state_rw::put(key, &date);
            written.insert(key);
        }

        let recorded = u32::try_from(written.len()).unwrap_or(u32::MAX);

        RunReport { date, recorded }
    }
}

export!(Node);
